changeSet.sql:
CREATE TABLE IF NOT EXISTS app.app_user ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), user_id BIGSERIAL NOT NULL, email_id VARCHAR(50) NOT NULL, name VARCHAR(50) NOT NULL, password VARCHAR(100) NOT NULL, CONSTRAINT app_user_pkey PRIMARY KEY (user_id), CONSTRAINT app_user_email_id_key UNIQUE (email_id) );
CREATE TABLE IF NOT EXISTS app.vendor ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), vendor_id BIGSERIAL NOT NULL, address VARCHAR(255), contact_number VARCHAR(15), email_id VARCHAR(50) NOT NULL, name VARCHAR(50) NOT NULL, CONSTRAINT vendor_pkey PRIMARY KEY (vendor_id), CONSTRAINT vendor_name_key UNIQUE (name) );
CREATE TABLE IF NOT EXISTS app.part ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), part_id BIGSERIAL NOT NULL, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), category_name VARCHAR(50), part_name VARCHAR(200), part_number VARCHAR(50), type VARCHAR(10), unit VARCHAR(10), CONSTRAINT part_pkey PRIMARY KEY (part_id), CONSTRAINT part_part_number_key UNIQUE (part_number) );
CREATE TABLE IF NOT EXISTS app.part_category ( delete_flag INTEGER DEFAULT 0, category_id BIGSERIAL NOT NULL, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), name VARCHAR(50) NOT NULL, CONSTRAINT part_category_pkey PRIMARY KEY (category_id), CONSTRAINT part_category_name_key UNIQUE (name) );
CREATE TABLE IF NOT EXISTS app.cost_factor ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), factor_id BIGSERIAL NOT NULL, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), factor_name VARCHAR(50), CONSTRAINT cost_factor_pkey PRIMARY KEY (factor_id) );
CREATE TABLE IF NOT EXISTS app.part_cost ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), part_cost_id BIGSERIAL NOT NULL, part_id BIGINT, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), vendor_id BIGINT, CONSTRAINT part_cost_pkey PRIMARY KEY (part_cost_id), CONSTRAINT part_cost_vendor_id_fkey FOREIGN KEY (vendor_id) REFERENCES app.vendor (vendor_id) ON DELETE CASCADE, CONSTRAINT part_cost_part_id_fkey FOREIGN KEY (part_id) REFERENCES app.part (part_id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS app.part_cost_cost_factor ( delete_flag INTEGER DEFAULT 0, value DOUBLE PRECISION NOT NULL, created_by BIGINT, created_date_time TIMESTAMPTZ(6), factor_id BIGINT, part_cost_cost_factor_id BIGSERIAL NOT NULL, part_cost_id BIGINT, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), CONSTRAINT part_cost_cost_factor_pkey PRIMARY KEY (part_cost_cost_factor_id), CONSTRAINT part_cost_cost_factor_part_cost_id_fkey FOREIGN KEY (part_cost_id) REFERENCES app.part_cost (part_cost_id) ON DELETE CASCADE, CONSTRAINT part_cost_cost_factor_factor_id_fkey FOREIGN KEY (factor_id) REFERENCES app.cost_factor (factor_id) );
CREATE TABLE IF NOT EXISTS app.part_unit ( delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), unit_id BIGSERIAL NOT NULL, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6), unit_name VARCHAR(50), CONSTRAINT part_unit_pkey PRIMARY KEY (unit_id), CONSTRAINT part_unit_unit_id_key UNIQUE (unit_name) );
CREATE TABLE IF NOT EXISTS app.bom ( delete_flag INTEGER DEFAULT 0, quantity DOUBLE PRECISION, created_by BIGINT, created_date_time TIMESTAMPTZ(6), parent_part_id BIGINT NOT NULL, part_id BIGINT NOT NULL, updated_by BIGINT, updated_date_time TIMESTAMPTZ(6) , CONSTRAINT bom_pkey PRIMARY KEY (parent_part_id, part_id), CONSTRAINT bom_parent_part_id_fkey FOREIGN KEY (parent_part_id) REFERENCES app.part (part_id) ON DELETE CASCADE, CONSTRAINT bom_part_id_fkey FOREIGN KEY (part_id) REFERENCES app.part (part_id) );

rollback.sql:
DROP TABLE app.app_user CASCADE;
DROP TABLE app.vendor CASCADE;
DROP TABLE app.part CASCADE;
DROP TABLE app.part_category CASCADE;
DROP TABLE app.cost_factor CASCADE;
DROP TABLE app.part_cost CASCADE;
DROP TABLE app.part_cost_cost_factor CASCADE;
DROP TABLE app.part_unit CASCADE;
DROP TABLE app.bom CASCADE;
